// ===== 整理歷史紀錄文字 =====
// 把「查詢股票歷史紀錄」讀到的 v_symbol_track_record 整理成文字，
// 讓「報告」節點在挑首選標的前，能看到每檔候選標的過去被推薦過幾次、結果如何。
// 依據：對 2025-2026 實際推薦資料的分析，重複推薦同一檔股票的達標率明顯低於
// 首次推薦（62% vs 38%），模型應避免在沒有新催化劑時重複挑選近期已推薦過的標的。

const upstream = $('整合報價').first().json;
const candidates = Array.isArray(upstream.availableSymbols) ? upstream.availableSymbols : [];

let records = [];
try {
  records = $input.all().map(i => i.json);
} catch (e) {
  console.log('[整理歷史紀錄文字] 取不到「查詢股票歷史紀錄」，本次不附歷史資訊：', e.message);
}

// 防呆：Supabase getAll 節點在部分分頁情況下可能吐出重複列（W4 已遇過同樣狀況），
// 這裡用 symbol 去重，保留第一筆
const bySymbol = new Map();
for (const r of records) {
  if (r && r.symbol && !bySymbol.has(r.symbol)) bySymbol.set(r.symbol, r);
}

const lines = candidates.map(sym => {
  const rec = bySymbol.get(sym);
  if (!rec || !rec.primary_rec_count) return `${sym}：尚未被推薦過`;

  const parts = [`共 ${rec.primary_rec_count} 次`];
  if (rec.last_primary_date) parts.push(`最近一次 ${rec.last_primary_date}`);
  const verified = Number(rec.target_hit_count || 0) + Number(rec.stop_hit_count || 0);
  if (verified > 0) {
    parts.push(`已驗證 ${verified} 次中：達標 ${rec.target_hit_count || 0} 次、觸停損 ${rec.stop_hit_count || 0} 次`);
  }
  if (rec.unverified_count > 0) parts.push(`另有 ${rec.unverified_count} 次尚未驗證完成`);

  return `${sym}：歷史推薦${parts.join('，')}`;
});

const historyText = lines.length
  ? lines.join('\n')
  : '（本次無候選標的資訊，略過歷史紀錄檢查）';

console.log('[整理歷史紀錄文字]\n' + historyText);

return [{
  json: {
    ...upstream,
    historyText,
  },
}];
